package de.corporate.lc.lc.service;
import de.corporate.lc.lc.api.LcTaskRequest;import de.corporate.lc.lc.domain.LcTask;import de.corporate.lc.lc.repository.LcTaskRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service public class LcTaskService {private final LcTaskRepository repo;private final LetterOfCreditService lcs;public LcTaskService(LcTaskRepository r,LetterOfCreditService l){repo=r;lcs=l;}public List<LcTask> forLc(UUID id){lcs.one(id);return repo.findByLetterOfCreditIdOrderByCompletedAscDueDateAscCreatedAtDesc(id);}public List<LcTask> open(){return repo.findByCompletedFalseOrderByDueDateAscCreatedAtAsc();}@Transactional public LcTask create(UUID lcId,LcTaskRequest request,String username){lcs.one(lcId);LcTask task=new LcTask();task.setLetterOfCreditId(lcId);task.setTitle(request.title().trim());task.setAssignedTo(clean(request.assignedTo()));task.setDueDate(request.dueDate());task.setCreatedBy(username);return repo.save(task);}@Transactional public LcTask complete(UUID lcId,UUID taskId,boolean completed){LcTask task=one(lcId,taskId);task.setCompleted(completed);task.setCompletedAt(completed?LocalDateTime.now():null);return task;}@Transactional public void delete(UUID lcId,UUID taskId){repo.delete(one(lcId,taskId));}private LcTask one(UUID lcId,UUID id){return repo.findById(id).filter(task->task.getLetterOfCreditId().equals(lcId)).orElseThrow(()->new NoSuchElementException("Aufgabe nicht gefunden"));}private String clean(String value){return value==null||value.isBlank()?null:value.trim();}}
